import{_ as t,a}from"./chunks/inline-runtime-298.Fy-nlImh.js";import{_ as r,o as i,c as n,a3 as s}from"./chunks/framework.BlfGB29P.js";const v=JSON.parse('{"title":"Palette, recently used and runtime","description":"Miniatures, saved recent widgets and runtime start/stop in Studio 0.1.299.","frontmatter":{"title":"Palette, recently used and runtime","description":"Miniatures, saved recent widgets and runtime start/stop in Studio 0.1.299."},"headers":[],"relativePath":"en/projects/grafik-visual-studio/palette-runtime.md","filePath":"en/projects/grafik-visual-studio/palette-runtime.md","lastUpdated":1794134439000}'),o={name:"en/projects/grafik-visual-studio/palette-runtime.md"};function d(l,e,c,p,u,h){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="palette-recently-used-and-runtime" tabindex="-1">Palette, recently used and runtime <a class="header-anchor" href="#palette-recently-used-and-runtime" aria-label="Permalink to &quot;Palette, recently used and runtime&quot;">​</a></h1><p><strong>Studio 0.1.299</strong> includes the new palette and the inline runtime previously tested locally as 0.1.298. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/grafik-visual-studio-v0.1.299" target="_blank" rel="noreferrer">GitHub update</a>.</p><h2 id="miniatures-and-descriptions" tabindex="-1">Miniatures and descriptions <a class="header-anchor" href="#miniatures-and-descriptions" aria-label="Permalink to &quot;Miniatures and descriptions&quot;">​</a></h2><p>The palette displays three equal tiles per row: miniature above, name below. Gauges use their own renderers with preview values; devices and clocks use Studio-owned static miniatures. Existing package images are retained. Hovering or keyboard focus opens a larger preview with a short description. UGSo sets and SVG-Line/LineBox/Math display names only. Previews never operate devices.</p><h2 id="recently-used" tabindex="-1">Recently used <a class="header-anchor" href="#recently-used" aria-label="Permalink to &quot;Recently used&quot;">​</a></h2><p>The independently collapsible <strong>Recently used</strong> section sits directly below search. It contains up to <strong>twelve distinct widget types</strong>, most recently inserted first. Inserting the same type again moves it to the front without creating a duplicate. Tiles, miniatures and descriptions match the regular palette.</p><p>Clicking inserts a new widget using the type’s defaults, <strong>not a copy of the last edited widget</strong>. Importing, pasting from the clipboard or merely selecting a widget does not change the list. Palette search also filters recent entries. Types from uninstalled packages are not offered; reinstalling a package can make them reappear.</p><p>The list and collapse state survive reloads and app updates in the <strong>same browser profile and web address</strong>. They are not synchronized between devices or exported with projects. Clearing browser data resets them. If browser storage is blocked, the list remains usable for the current session. Other settings and project files are unchanged.</p><p><img src="'+t+'" alt="Recently used widgets on .177"></p><h2 id="runtime-over-the-canvas" tabindex="-1">Runtime over the canvas <a class="header-anchor" href="#runtime-over-the-canvas" aria-label="Permalink to &quot;Runtime over the canvas&quot;">​</a></h2><p><strong>▶</strong> beside the page tabs saves the current project and starts an isolated runtime over the canvas. <strong>■</strong> stops it. Palette, properties and editing tools, including shortcuts, are dimmed and locked. Page navigation and the separate runtime window remain available. Failed saves prevent runtime from starting.</p><p>Stopping restores the original editor page with selection, history and scroll position. Preview navigation does not change the editor page. Embedded own-tab widgets retain their starting context. The old Editor/Runtime mode links at the top are removed; <strong>New tab</strong> still opens the standalone runtime. Runtime widgets can operate real HA devices as before.</p><p><img src="'+a+'" alt="Inline runtime with dimmed editing tools"></p><h2 id="preservation-and-verification" tabindex="-1">Preservation and verification <a class="header-anchor" href="#preservation-and-verification" aria-label="Permalink to &quot;Preservation and verification&quot;">​</a></h2><p>Existing projects, widget types, CSS and color settings remain intact. New browser preferences use a separate storage key. No VIS-2 code or artwork was copied for these features.</p><p>On November 8, 2026, 0.1.299 was verified on .177 (HA 2026.11.0/ARM64) and .193 (HA 2026.10.4/amd64): recent thumbnails, ordering without duplicates, insertion, collapse and persistence after reload, and locking during inline runtime. Test insertions were undone; the existing 13 and 11 widgets were preserved. The palette and start/stop were also checked with save, page navigation and returning to the editor. All 23 JavaScript and 17 Python tests passed. Details: <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/docs" target="_blank" rel="noreferrer">source and test reports</a>.</p>',16)])])}const f=r(o,[["render",d]]);export{v as __pageData,f as default};
